[
  {
    "name": "老板娘苏姨",
    "description": "深夜小馆的主理人，50岁出头，曾是米其林餐厅主厨，因丧夫后辞职隐于小巷，独自经营这间只做夜宵的小馆",
    "appearance": "48岁，圆润温和的脸庞，眼角有细纹，短发齐耳染着低调深棕，眼神温暖却带有一丝阅历的哀愁",
    "costume": "藏青色棉麻围裙，内搭米白色棉麻衬衫，袖口卷起，腕上一只老式银色手表",
    "personality": "沉默寡言却洞察人心，从不多问，只用一道菜回应食客的伤痛"
  },
  {
    "name": "林小念",
    "description": "本集主角，刚毕业的插画师，外婆刚去世一周，独自来到陌生城市工作",
    "appearance": "24岁，齐刘海黑长直发，眉眼清秀带点倔强，眼下有淡淡黑眼圈，皮肤偏白",
    "costume": "卡其色风衣，内搭奶白色高领毛衣，深灰色围巾，背着帆布双肩包",
    "personality": "外冷内热，习惯用沉默保护自己，心里藏着对逝去亲人的愧疚"
  },
  {
    "name": "外婆（回忆中）",
    "description": "林小念最亲的人，已故，只出现在回忆镜头与照片里",
    "appearance": "72岁，满头银发梳得一丝不苟，永远系着蓝白碎花围裙，满脸皱纹却笑得最暖",
    "costume": "蓝白碎花棉布围裙，深蓝色对襟棉袄",
    "personality": "慈祥、唠叨、做得一手好阳春面，是小念童年最深的味道"
  }
]

[
  {
    "name": "深夜小馆·室内",
    "description": "小巷深处的深夜食堂，仅8个座位，吧台环绕开放式厨房，墙上挂满泛黄老照片与手写菜单",
    "visualStyle": "钨丝灯暖黄主光，吧台上方一盏孤灯，玻璃窗映出雨夜霓虹，蒸汽弥漫，胶片颗粒感"
  },
  {
    "name": "深夜小馆·门口",
    "description": "一条湿漉漉的青石板小巷尽头，一扇木门透出暖黄灯光，门上挂着褪色红灯笼",
    "visualStyle": "雨夜湿润反光，冷蓝街景与暖黄门内光形成强烈对比，烟雾缭绕"
  },
  {
    "name": "回忆·外婆家厨房",
    "description": "老式筒子楼的小厨房，窗户对着梧桐树，阳光透过碎花窗帘洒在灶台上",
    "visualStyle": "明亮柔和的自然光，高调暖白，泛黄回忆滤镜，轻微过曝，柔焦"
  },
  {
    "name": "林小念出租屋",
    "description": "逼仄的单间，一张床、一张桌、一盏台灯，桌上放着没拆封的行李",
    "visualStyle": "冷青色调，台灯孤光，窗外城市霓虹杂乱，雨滴打湿玻璃"
  }
]

{
  "scenes": [
    {
      "location": "深夜小馆·门口",
      "time": "夜晚·雨",
      "characters": [
        "林小念"
      ],
      "action": "雨夜小巷，林小念撑着伞独自走过，停在透出暖黄灯光的深夜小馆门口，犹豫片刻后推门而入",
      "dialogue": "",
      "mood": "孤独、迷茫、被一束暖光吸引"
    },
    {
      "location": "深夜小馆·室内",
      "time": "夜晚",
      "characters": [
        "林小念",
        "老板娘苏姨"
      ],
      "action": "林小念进门，环顾四周，在吧台最角落坐下，苏姨没有抬头，只问了一句：吃点什么？",
      "dialogue": "苏姨：吃点什么？\n小念（小声）：有什么……简单的吗？",
      "mood": "安静、疏离，两个陌生人之间的试探"
    },
    {
      "location": "深夜小馆·室内",
      "time": "夜晚",
      "characters": [
        "老板娘苏姨",
        "林小念"
      ],
      "action": "苏姨抬头看了她一眼，没有多问，转身开始煮面，只下面、不多话，灶火映着她的脸",
      "dialogue": "苏姨（低声自语）：阳春面，最简单的。",
      "mood": "温柔的洞察，一碗即将治愈她的面正在诞生"
    },
    {
      "location": "回忆·外婆家厨房",
      "time": "白天（回忆）",
      "characters": [
        "外婆",
        "林小念（童年）"
      ],
      "action": "切回到童年，外婆在小厨房里揉面，小念站在凳子上看，外婆笑着往她鼻尖点面粉",
      "dialogue": "外婆：丫头啊，记着，外面再大的馆子，也比不上家里这碗面。",
      "mood": "温暖明亮，最珍贵的童年味道"
    },
    {
      "location": "深夜小馆·室内",
      "time": "夜晚",
      "characters": [
        "林小念",
        "老板娘苏姨"
      ],
      "action": "回到现实，面端到小念面前，葱花碧绿、汤色清亮，热气氤氲，小念愣住，眼泪突然掉下来",
      "dialogue": "",
      "mood": "情绪决堤，沉默的眼泪最动人"
    },
    {
      "location": "深夜小馆·室内",
      "time": "夜晚",
      "characters": [
        "林小念",
        "老板娘苏姨"
      ],
      "action": "小念低头吃面，每一口都慢，泪水混进面汤。苏姨默默递上一张干净手帕，然后转身擦杯子，不看她",
      "dialogue": "苏姨（背对着）：慢慢吃，不急。小馆不打烊。",
      "mood": "克制却汹涌的温情，被陌生人接住的痛"
    },
    {
      "location": "深夜小馆·室内",
      "time": "凌晨",
      "characters": [
        "林小念",
        "老板娘苏姨"
      ],
      "action": "小念吃完，把碗推到一边，从包里拿出外婆生前最爱用的那只蓝白碎花手帕，包在碗上。她起身，留下钱，对苏姨深深鞠了一躬",
      "dialogue": "小念：谢谢您。这碗面，跟我外婆做的……一模一样。",
      "mood": "释然，一场迟到却完整的告别"
    },
    {
      "location": "深夜小馆·门口",
      "time": "凌晨·雨停",
      "characters": [
        "林小念"
      ],
      "action": "雨停了，小念走出小馆，抬头看天，深吸一口气。路灯映着湿漉漉的青石板，她终于露出一个浅浅的笑",
      "dialogue": "",
      "mood": "雨过天晴，最轻的释怀"
    }
  ]
}
